# Script S5. Cross-spectral coherence and phase relationships among dataloggers# Thermal Behavior of Crocodile Caves in Central Belize # Authors: Wynne, J.J., Shaffer, I.N., Roberts, J.# Script Author: J. Judson Wynne# R-Studio Version: 2025.05.1+513 (2025.05.1+513)# Required packages:# readxl# tidyverse# Input File# CrocCave_Data.xlsx# Output:# Cross-spectral coherence and phase results, Raw time series (Table 5 from paper)# Cross-spectral coherence and phase, Detrended time series (Table S1 from Supp. Mat. File 1)# Required packageslibrary(readxl)library(tidyverse)# Settingsxlsx_file <- "CrocCave_Data.xlsx"# Import all worksheetssheets <- excel_sheets(xlsx_file); dat <- map_dfr(sheets, function(sh){read_excel(xlsx_file, sheet = sh) %>% mutate(Sheet = sh, Logger = str_extract(sh, "L[1-5]"), Cave = ifelse(str_detect(sh, "Croc2"), "Croc 2", "KHC"))})# Create Temporal Window# Dates represent when caves were floodeddat <- dat %>% mutate(DateTime = as.POSIXct(paste(format(Date, "%Y-%m-%d"), format(Time, "%H:%M:%S")), format = "%Y-%m-%d %H:%M:%S"), Temp = `Temperature (C)`, Hour = hour(DateTime))analysis_start <- as.POSIXct("2022-08-01 00:00:00") analysis_end <- as.POSIXct("2023-02-18 23:59:59")  dat <- dat %>% filter(DateTime >= analysis_start, DateTime <= analysis_end)# Table 5 from paper# Cross-coherence and phase using raw datacalc_pair_raw <- function(df, logger1, logger2) {dat_pair <- df %>% filter(Logger %in% c(logger1, logger2)) %>% select(DateTime, Logger, Temp) %>% pivot_wider(names_from = Logger, values_from = Temp) %>% drop_na(all_of(c(logger1, logger2))) %>% arrange(DateTime); overlap_h <- nrow(dat_pair); if (overlap_h < 10) return(NULL); x <- dat_pair[[logger1]]; y <- dat_pair[[logger2]]; sp <- spec.pgram(cbind(x, y), demean = TRUE, detrend = FALSE, spans = c(5, 5), plot = FALSE); period_h <- 1 / sp$freq; valid <- period_h >= 2 & period_h <= 168; peak_idx <- which(valid)[which.max(sp$coh[valid])]; peak_coh2 <- sp$coh[peak_idx]; peak_freq <- sp$freq[peak_idx]; peak_phase <- sp$phase[peak_idx]; delay_h <- peak_phase / (2 * pi * peak_freq); tibble(Pair = paste(logger1, logger2, sep = "-"), Overlap_h = overlap_h, Coherency2 = round(peak_coh2, 2), Delay_h = round(delay_h, 1))}  # Raw time series, All pairwise comparisonsresults_raw <- list(); for (cave_name in unique(dat$Cave)) { cave_dat <- filter(dat, Cave == cave_name); loggers <- sort(unique(cave_dat$Logger)); pairs <- combn(loggers, 2, simplify = FALSE); cave_results <- map_dfr(pairs, ~calc_pair_raw(cave_dat, .x[1], .x[2])); cave_results$Cave <- cave_name; results_raw[[cave_name]] <- cave_results}  table5_raw <- bind_rows(results_raw) %>% select(Cave, Pair, Overlap_h, Coherency2, Delay_h) %>% arrange(Cave, Pair)  # Table S1, Supplemental Material File #1# Detrended time series, Cross-coherence and phasecalc_pair_detrend <- function(df, logger1, logger2) { dat_pair <- df %>% filter(Logger %in% c(logger1, logger2)) %>% select(DateTime, Logger, Temp) %>% pivot_wider(names_from = Logger, values_from = Temp) %>% drop_na(all_of(c(logger1, logger2))) %>% arrange(DateTime); overlap_h <- nrow(dat_pair); if (overlap_h < 10) return(NULL); x <- dat_pair[[logger1]]; y <- dat_pair[[logger2]]; sp <- spec.pgram(cbind(x, y), demean = TRUE, detrend = TRUE, spans = c(5, 5), plot = FALSE); period_h <- 1 / sp$freq; valid <- period_h >= 2 & period_h <= 168; peak_idx <- which(valid)[which.max(sp$coh[valid])]; peak_coh2 <- sp$coh[peak_idx]; peak_freq <- sp$freq[peak_idx]; peak_phase <- sp$phase[peak_idx]; delay_h <- peak_phase / (2 * pi * peak_freq); tibble(Pair = paste(logger1, logger2, sep = "-"), Overlap_h = overlap_h, Coherency2 = round(peak_coh2, 2), Delay_h = round(delay_h, 1)) }  # Detrended time series, All pairwise comparisonsresults_detrend <- list(); for (cave_name in unique(dat$Cave)) { cave_dat <- filter(dat, Cave == cave_name); loggers <- sort(unique(cave_dat$Logger)); pairs <- combn(loggers, 2, simplify = FALSE); cave_results <- map_dfr(pairs, ~calc_pair_detrend(cave_dat, .x[1], .x[2])); cave_results$Cave <- cave_name; results_detrend[[cave_name]] <- cave_results }  tableS1_detrend <- bind_rows(results_detrend) %>% select(Cave, Pair, Overlap_h, Coherency2, Delay_h) %>% arrange(Cave, Pair)  # Raw and detrended time series, Export tableswrite.csv(table5_raw, "Table5_CrossSpectralCoherence_RAW.csv", row.names = FALSE)write.csv(tableS1_detrend, "TableS1_CrossSpectralCoherence_Detrend.csv", row.names = FALSE)